// Phase 4 — zero copy (cache bypass) on one kernel + reuse crossover (see prompts/04_zero_copy.md)
// Build: nvcc -O3 -arch=sm_87 -o phase4_bench phase4_bench.cu -lcuda
//
// Reads a test-point config CSV (generated by scripts/gen_test_points.py from upstream
// findings.json) describing each (test_point_id, mode, config, sm_split, sizes, blocks) cell.
// For each test point, runs both the "cached" baseline and the "zerocopy" variant (large
// kernel's A/B routed through mapped pinned memory instead of cudaMalloc) across reuse_N in
// {1,2,4,8,16,32}, and writes results/phase4_results.csv per the schema in the prompt.
//
// Green context (config=="green") uses the CUDA 12.4+ driver API. If the toolkit predates
// 12.4 or the driver calls fail at runtime, green rows are SKIPPED with a stderr message —
// never faked (00_conventions.md, prompts/03_green_context.md, prompts/04_zero_copy.md).
#include <cuda_runtime.h>
#include <cuda.h>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#define CUDA_CHECK(call)                                                          \
    do {                                                                          \
        cudaError_t _err = (call);                                                \
        if (_err != cudaSuccess) {                                                \
            fprintf(stderr, "CUDA error %s:%d: %s\n", __FILE__, __LINE__,          \
                    cudaGetErrorString(_err));                                     \
            exit(1);                                                              \
        }                                                                          \
    } while (0)

// Driver-API errors during green-context setup are NOT fatal: we report and skip the row
// (see trySetupGreenContext). This macro is only for calls that must succeed once we've
// committed to the green path.
#define CU_CHECK_OR_RETURN_FALSE(call)                                            \
    do {                                                                          \
        CUresult _res = (call);                                                   \
        if (_res != CUDA_SUCCESS) {                                               \
            const char* _msg = nullptr;                                          \
            cuGetErrorString(_res, &_msg);                                        \
            fprintf(stderr, "green-context driver call failed %s:%d: %s\n",       \
                    __FILE__, __LINE__, _msg ? _msg : "unknown");                 \
            return false;                                                         \
        }                                                                          \
    } while (0)

__global__ void addKernel(const float* __restrict__ A, const float* __restrict__ B,
                           float* __restrict__ C, size_t n) {
    size_t stride = (size_t)gridDim.x * blockDim.x;
    for (size_t i = (size_t)blockIdx.x * blockDim.x + threadIdx.x; i < n; i += stride) {
        C[i] = A[i] + B[i];
    }
}

__global__ void fillKernel(float* __restrict__ A, float* __restrict__ B, size_t n) {
    size_t stride = (size_t)gridDim.x * blockDim.x;
    for (size_t i = (size_t)blockIdx.x * blockDim.x + threadIdx.x; i < n; i += stride) {
        A[i] = 1.0f;
        B[i] = 2.0f;
    }
}

// ---- env / device info (best-effort; Jetson-specific probes fall back gracefully) ----
// Duplicated from Phase 1 by design: 00_conventions.md isolates phases to their own
// directory, so each phase's src is self-contained rather than sharing a common header.

static std::string trim(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    size_t b = s.find_last_not_of(" \t\r\n");
    if (a == std::string::npos) return "";
    return s.substr(a, b - a + 1);
}

static std::string queryPowerMode() {
    FILE* pipe = popen("nvpmodel -q 2>/dev/null", "r");
    if (!pipe) return "unknown";
    std::string result = "unknown";
    char buf[256];
    while (fgets(buf, sizeof(buf), pipe)) {
        std::string line(buf);
        auto pos = line.find("NV Power Mode");
        if (pos != std::string::npos) {
            auto colon = line.find(':', pos);
            if (colon != std::string::npos) result = trim(line.substr(colon + 1));
        }
    }
    pclose(pipe);
    return result;
}

static double querySocTempC() {
    static const char* candidates[] = {
        "/sys/devices/virtual/thermal/thermal_zone0/temp",
        "/sys/class/thermal/thermal_zone0/temp",
    };
    for (const char* path : candidates) {
        FILE* f = fopen(path, "r");
        if (!f) continue;
        long milli = 0;
        int got = fscanf(f, "%ld", &milli);
        fclose(f);
        if (got == 1) return milli / 1000.0;
    }
    return -1.0;
}

static std::string versionStr(int v) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%d.%d", v / 1000, (v % 100) / 10);
    return buf;
}

struct EnvInfo {
    int gpu_clock_mhz;
    std::string power_mode;
    double soc_temp_c;
    std::string cuda_version;
    std::string driver_version;
    int sm_count;
};

static EnvInfo queryEnv() {
    EnvInfo e;
    int runtimeVer = 0, driverVer = 0, clockKhz = 0, smCount = 0;
    CUDA_CHECK(cudaRuntimeGetVersion(&runtimeVer));
    CUDA_CHECK(cudaDriverGetVersion(&driverVer));
    CUDA_CHECK(cudaDeviceGetAttribute(&clockKhz, cudaDevAttrClockRate, 0));
    CUDA_CHECK(cudaDeviceGetAttribute(&smCount, cudaDevAttrMultiProcessorCount, 0));
    e.gpu_clock_mhz = clockKhz / 1000;
    e.cuda_version = versionStr(runtimeVer);
    e.driver_version = versionStr(driverVer);
    e.power_mode = queryPowerMode();
    e.soc_temp_c = querySocTempC();
    e.sm_count = smCount;
    return e;
}

// ---- stats ----

struct Stats {
    double median, min, max, stddev;
};

static Stats computeStats(std::vector<double> v) {
    std::sort(v.begin(), v.end());
    Stats s;
    size_t n = v.size();
    s.min = v.front();
    s.max = v.back();
    s.median = (n % 2 == 0) ? (v[n / 2 - 1] + v[n / 2]) / 2.0 : v[n / 2];
    double mean = 0;
    for (double x : v) mean += x;
    mean /= n;
    double var = 0;
    for (double x : v) var += (x - mean) * (x - mean);
    var /= n;
    s.stddev = std::sqrt(var);
    return s;
}

// ---- buffers: cudaMalloc (cached) or mapped pinned host memory (zero copy) ----

struct Buffer {
    float* host = nullptr;  // valid only when isZeroCopy
    float* dev = nullptr;   // always the device-usable pointer for kernel args
    bool isZeroCopy = false;
    size_t n_elems = 0;
};

static Buffer allocBuffer(size_t n_elems, bool zeroCopy) {
    Buffer b;
    b.n_elems = n_elems;
    b.isZeroCopy = zeroCopy;
    if (zeroCopy) {
        CUDA_CHECK(cudaHostAlloc((void**)&b.host, n_elems * sizeof(float), cudaHostAllocMapped));
        CUDA_CHECK(cudaHostGetDevicePointer((void**)&b.dev, b.host, 0));
    } else {
        CUDA_CHECK(cudaMalloc(&b.dev, n_elems * sizeof(float)));
    }
    return b;
}

static void freeBuffer(Buffer& b) {
    if (b.isZeroCopy) {
        CUDA_CHECK(cudaFreeHost(b.host));
    } else {
        CUDA_CHECK(cudaFree(b.dev));
    }
    b.host = nullptr;
    b.dev = nullptr;
}

// ---- green context (CUDA >= 12.4 driver API); compiled out on older toolkits ----

struct GreenContextHandle {
    bool active = false;
#if defined(CUDA_VERSION) && CUDA_VERSION >= 12040
    CUgreenCtx gctx0 = nullptr;
    CUgreenCtx gctx1 = nullptr;
#endif
};

#if defined(CUDA_VERSION) && CUDA_VERSION >= 12040
// Splits the device's SMs into two disjoint pools of sizes smK0 / smK1 and creates one
// green context + stream per pool. Returns false (no partial state left active) on any
// driver-API failure so the caller can skip the row rather than silently running "shared".
static bool trySetupGreenContext(int smK0, int smK1, GreenContextHandle& gc,
                                  cudaStream_t& streamK0, cudaStream_t& streamK1) {
    CUdevice dev;
    CU_CHECK_OR_RETURN_FALSE(cuInit(0));
    CU_CHECK_OR_RETURN_FALSE(cuDeviceGet(&dev, 0));

    CUdevResource input;
    CU_CHECK_OR_RETURN_FALSE(cuDeviceGetDevResource(dev, &input, CU_DEV_RESOURCE_TYPE_SM));

    // Split off a smK0-SM group, then a smK1-SM group, from the remaining pool.
    CUdevResource group0[1];
    CUdevResource remaining0;
    unsigned int nbGroups0 = 1;
    CU_CHECK_OR_RETURN_FALSE(cuDevSmResourceSplitByCount(group0, &nbGroups0, &input, &remaining0,
                                                          0, (unsigned int)smK0));

    CUdevResource group1[1];
    CUdevResource remaining1;
    unsigned int nbGroups1 = 1;
    CU_CHECK_OR_RETURN_FALSE(cuDevSmResourceSplitByCount(group1, &nbGroups1, &remaining0,
                                                          &remaining1, 0, (unsigned int)smK1));

    CUdevResourceDesc desc0, desc1;
    CU_CHECK_OR_RETURN_FALSE(cuDevResourceGenerateDesc(&desc0, group0, 1));
    CU_CHECK_OR_RETURN_FALSE(cuDevResourceGenerateDesc(&desc1, group1, 1));

    CU_CHECK_OR_RETURN_FALSE(cuGreenCtxCreate(&gc.gctx0, desc0, dev, CU_GREEN_CTX_DEFAULT_STREAM));
    CU_CHECK_OR_RETURN_FALSE(cuGreenCtxCreate(&gc.gctx1, desc1, dev, CU_GREEN_CTX_DEFAULT_STREAM));

    CUstream cuS0, cuS1;
    CU_CHECK_OR_RETURN_FALSE(cuGreenCtxStreamCreate(&cuS0, gc.gctx0, CU_STREAM_NON_BLOCKING, 0));
    CU_CHECK_OR_RETURN_FALSE(cuGreenCtxStreamCreate(&cuS1, gc.gctx1, CU_STREAM_NON_BLOCKING, 0));

    // CUstream and cudaStream_t are binary-compatible (both opaque CUstream_st*), so the
    // runtime API's <<<>>> launch syntax can target a stream created via the driver API.
    streamK0 = (cudaStream_t)cuS0;
    streamK1 = (cudaStream_t)cuS1;
    gc.active = true;
    return true;
}

static void destroyGreenContext(GreenContextHandle& gc, cudaStream_t s0, cudaStream_t s1) {
    if (!gc.active) return;
    cuStreamDestroy((CUstream)s0);
    cuStreamDestroy((CUstream)s1);
    cuGreenCtxDestroy(gc.gctx0);
    cuGreenCtxDestroy(gc.gctx1);
    gc.active = false;
}
#else
static bool trySetupGreenContext(int, int, GreenContextHandle&, cudaStream_t&, cudaStream_t&) {
    fprintf(stderr,
            "green context unsupported: built against CUDA_VERSION=%d (< 12040). "
            "Rebuild with CUDA 12.4+ toolkit to enable config=green rows.\n",
            (int)CUDA_VERSION);
    return false;
}
static void destroyGreenContext(GreenContextHandle&, cudaStream_t, cudaStream_t) {}
#endif

// ---- test-point config (from scripts/gen_test_points.py) ----

struct TestPoint {
    std::string test_point_id;
    std::string mode;    // symmetric|asymmetric
    std::string config;  // shared|green
    int sm_split_k0 = 0;
    int sm_split_k1 = 0;
    size_t k0_bytes = 0;
    size_t k1_bytes = 0;
    int large_kernel_id = 1;  // 0 or 1: which kernel gets the zero-copy treatment
    int blocks_k0 = 256;
    int blocks_k1 = 256;
    int threads_per_block = 256;
};

static std::vector<std::string> splitCsvLine(const std::string& line) {
    std::vector<std::string> out;
    std::stringstream ss(line);
    std::string field;
    while (std::getline(ss, field, ',')) out.push_back(trim(field));
    return out;
}

static std::vector<TestPoint> readTestPoints(const std::string& path) {
    std::ifstream f(path);
    if (!f) {
        fprintf(stderr, "Cannot open test-point config %s\n", path.c_str());
        exit(1);
    }
    std::string header;
    std::getline(f, header);
    std::vector<std::string> cols = splitCsvLine(header);
    std::map<std::string, int> idx;
    for (size_t i = 0; i < cols.size(); ++i) idx[cols[i]] = (int)i;

    auto need = [&](const char* name) -> int {
        auto it = idx.find(name);
        if (it == idx.end()) {
            fprintf(stderr, "test-point config missing required column '%s'\n", name);
            exit(1);
        }
        return it->second;
    };
    int cId = need("test_point_id"), cMode = need("mode"), cConfig = need("config");
    int cSmK0 = need("sm_split_k0"), cSmK1 = need("sm_split_k1");
    int cK0B = need("k0_bytes"), cK1B = need("k1_bytes"), cLarge = need("large_kernel_id");
    int cBlk0 = need("blocks_k0"), cBlk1 = need("blocks_k1"), cTpb = need("threads_per_block");

    std::vector<TestPoint> points;
    std::string line;
    while (std::getline(f, line)) {
        if (trim(line).empty()) continue;
        std::vector<std::string> f2 = splitCsvLine(line);
        TestPoint tp;
        tp.test_point_id = f2[cId];
        tp.mode = f2[cMode];
        tp.config = f2[cConfig];
        tp.sm_split_k0 = std::atoi(f2[cSmK0].c_str());
        tp.sm_split_k1 = std::atoi(f2[cSmK1].c_str());
        tp.k0_bytes = std::strtoull(f2[cK0B].c_str(), nullptr, 10);
        tp.k1_bytes = std::strtoull(f2[cK1B].c_str(), nullptr, 10);
        tp.large_kernel_id = std::atoi(f2[cLarge].c_str());
        tp.blocks_k0 = std::atoi(f2[cBlk0].c_str());
        tp.blocks_k1 = std::atoi(f2[cBlk1].c_str());
        tp.threads_per_block = std::atoi(f2[cTpb].c_str());
        points.push_back(tp);
    }
    return points;
}

// ---- one measured cell: both kernels launched concurrently, reuse_N times each ----

struct CellResult {
    double wall_ms_median;
    double k0_ms_median;
    double k1_ms_median;
    double agg_GBps_median;
    double k0_GBps_median;
    double k1_GBps_median;
    double wall_relstd;
};

static CellResult measureConcurrentCell(const Buffer& A0, const Buffer& B0, Buffer& C0, size_t n0,
                                         const Buffer& A1, const Buffer& B1, Buffer& C1, size_t n1,
                                         int blocks0, int blocks1, int tpb, int reuseN,
                                         cudaStream_t s0, cudaStream_t s1, int trials) {
    // warm-up: untimed launches before the measured cell (00_conventions.md #4)
    for (int w = 0; w < 3; ++w) {
        addKernel<<<blocks0, tpb, 0, s0>>>(A0.dev, B0.dev, C0.dev, n0);
        addKernel<<<blocks1, tpb, 0, s1>>>(A1.dev, B1.dev, C1.dev, n1);
    }
    CUDA_CHECK(cudaStreamSynchronize(s0));
    CUDA_CHECK(cudaStreamSynchronize(s1));

    cudaEvent_t start0, stop0, start1, stop1;
    CUDA_CHECK(cudaEventCreate(&start0));
    CUDA_CHECK(cudaEventCreate(&stop0));
    CUDA_CHECK(cudaEventCreate(&start1));
    CUDA_CHECK(cudaEventCreate(&stop1));

    std::vector<double> wallMs, k0Ms, k1Ms;
    wallMs.reserve(trials);
    k0Ms.reserve(trials);
    k1Ms.reserve(trials);

    for (int t = 0; t < trials; ++t) {
        CUDA_CHECK(cudaDeviceSynchronize());
        auto cpuStart = std::chrono::high_resolution_clock::now();

        CUDA_CHECK(cudaEventRecord(start0, s0));
        for (int j = 0; j < reuseN; ++j) addKernel<<<blocks0, tpb, 0, s0>>>(A0.dev, B0.dev, C0.dev, n0);
        CUDA_CHECK(cudaEventRecord(stop0, s0));

        CUDA_CHECK(cudaEventRecord(start1, s1));
        for (int j = 0; j < reuseN; ++j) addKernel<<<blocks1, tpb, 0, s1>>>(A1.dev, B1.dev, C1.dev, n1);
        CUDA_CHECK(cudaEventRecord(stop1, s1));

        CUDA_CHECK(cudaStreamSynchronize(s0));
        CUDA_CHECK(cudaStreamSynchronize(s1));
        auto cpuEnd = std::chrono::high_resolution_clock::now();

        float ms0 = 0, ms1 = 0;
        CUDA_CHECK(cudaEventElapsedTime(&ms0, start0, stop0));
        CUDA_CHECK(cudaEventElapsedTime(&ms1, start1, stop1));
        double wall = std::chrono::duration<double, std::milli>(cpuEnd - cpuStart).count();

        wallMs.push_back(wall);
        k0Ms.push_back(ms0);
        k1Ms.push_back(ms1);
    }

    CUDA_CHECK(cudaEventDestroy(start0));
    CUDA_CHECK(cudaEventDestroy(stop0));
    CUDA_CHECK(cudaEventDestroy(start1));
    CUDA_CHECK(cudaEventDestroy(stop1));

    Stats wallStats = computeStats(wallMs);
    Stats k0Stats = computeStats(k0Ms);
    Stats k1Stats = computeStats(k1Ms);

    double bytes0 = 3.0 * (double)n0 * 4.0 * (double)reuseN;  // A read + B read + C write
    double bytes1 = 3.0 * (double)n1 * 4.0 * (double)reuseN;

    CellResult r;
    r.wall_ms_median = wallStats.median;
    r.k0_ms_median = k0Stats.median;
    r.k1_ms_median = k1Stats.median;
    r.k0_GBps_median = bytes0 / (k0Stats.median / 1000.0) / 1e9;
    r.k1_GBps_median = bytes1 / (k1Stats.median / 1000.0) / 1e9;
    r.agg_GBps_median = (bytes0 + bytes1) / (wallStats.median / 1000.0) / 1e9;
    r.wall_relstd = wallStats.stddev / wallStats.median;
    return r;
}

// ---- correctness check ----

static bool checkCorrectness(const Buffer& C, size_t n_elems) {
    size_t nsample = std::min<size_t>(n_elems, 4096);
    std::vector<float> host(nsample);
    CUDA_CHECK(cudaMemcpy(host.data(), C.dev, nsample * sizeof(float), cudaMemcpyDeviceToHost));
    for (size_t i = 0; i < nsample; ++i) {
        if (std::fabs(host[i] - 3.0f) > 1e-5f) return false;
    }
    return true;
}

int main(int argc, char** argv) {
    std::string configPath = "results/test_points_config.csv";
    std::string outPath = "results/phase4_results.csv";
    std::string profileOneId;   // if set: run only this test_point_id
    std::string profilePath;    // "cached" or "zerocopy", required with --profile-one
    int profileReuse = 1;
    int trials = 10;

    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "--config" && i + 1 < argc) configPath = argv[++i];
        else if (a == "--out" && i + 1 < argc) outPath = argv[++i];
        else if (a == "--profile-one" && i + 1 < argc) profileOneId = argv[++i];
        else if (a == "--profile-path" && i + 1 < argc) profilePath = argv[++i];
        else if (a == "--profile-reuse" && i + 1 < argc) profileReuse = std::atoi(argv[++i]);
        else if (a == "--trials" && i + 1 < argc) trials = std::atoi(argv[++i]);
    }

    // Must be set before any context-creating CUDA call for cudaHostGetDevicePointer to work.
    CUDA_CHECK(cudaSetDeviceFlags(cudaDeviceMapHost));

    EnvInfo env = queryEnv();
    fprintf(stderr, "GPU clock: %d MHz, SMs: %d, power mode: %s, SoC temp: %.1f C, CUDA %s, driver %s\n",
            env.gpu_clock_mhz, env.sm_count, env.power_mode.c_str(), env.soc_temp_c,
            env.cuda_version.c_str(), env.driver_version.c_str());

    std::vector<TestPoint> points = readTestPoints(configPath);
    if (!profileOneId.empty()) {
        std::vector<TestPoint> filtered;
        for (auto& tp : points)
            if (tp.test_point_id == profileOneId) filtered.push_back(tp);
        if (filtered.empty()) {
            fprintf(stderr, "--profile-one %s not found in %s\n", profileOneId.c_str(), configPath.c_str());
            return 1;
        }
        points = filtered;
        if (profilePath.empty()) {
            fprintf(stderr, "--profile-one requires --profile-path cached|zerocopy\n");
            return 1;
        }
    }

    const std::vector<int> reuseNs = profileOneId.empty()
                                          ? std::vector<int>{1, 2, 4, 8, 16, 32}
                                          : std::vector<int>{profileReuse};

    FILE* csv = fopen(outPath.c_str(), profileOneId.empty() ? "w" : "a");
    if (!csv) {
        fprintf(stderr, "Cannot open %s for writing\n", outPath.c_str());
        return 1;
    }
    if (profileOneId.empty()) {
        fprintf(csv,
                "test_point_id,mode,config,sm_split,"
                "k0_bytes,k1_bytes,large_kernel_id,large_kernel_path,reuse_N,"
                "blocks_k0,blocks_k1,threads_per_block,trials,"
                "wall_ms_median,agg_GBps_median,k0_GBps_median,k1_GBps_median,"
                "delta_vs_cached_pct,l2_hit_rate_zc,l2_hit_rate_cached,"
                "gpu_clock_mhz,power_mode,soc_temp_c,cuda_version,driver_version\n");
    }

    bool anyCorrectnessFail = false;

    for (auto& tp : points) {
        size_t n0 = tp.k0_bytes / sizeof(float);
        size_t n1 = tp.k1_bytes / sizeof(float);
        bool k0IsLarge = (tp.large_kernel_id == 0);
        bool k1IsLarge = (tp.large_kernel_id == 1);

        std::vector<std::string> paths = profileOneId.empty()
                                              ? std::vector<std::string>{"cached", "zerocopy"}
                                              : std::vector<std::string>{profilePath};

        std::map<int, double> cachedAggByReuse;  // reuse_N -> agg_GBps, for delta_vs_cached_pct
        bool didCorrectnessCheck = false;

        for (auto& path : paths) {
            bool zc = (path == "zerocopy");

            Buffer A0 = allocBuffer(n0, zc && k0IsLarge);
            Buffer B0 = allocBuffer(n0, zc && k0IsLarge);
            Buffer C0 = allocBuffer(n0, false);
            Buffer A1 = allocBuffer(n1, zc && k1IsLarge);
            Buffer B1 = allocBuffer(n1, zc && k1IsLarge);
            Buffer C1 = allocBuffer(n1, false);

            fillKernel<<<256, tp.threads_per_block>>>(A0.dev, B0.dev, n0);
            fillKernel<<<256, tp.threads_per_block>>>(A1.dev, B1.dev, n1);
            CUDA_CHECK(cudaDeviceSynchronize());

            cudaStream_t s0, s1;
            GreenContextHandle gc;
            bool streamsReady;
            if (tp.config == "green") {
                streamsReady = trySetupGreenContext(tp.sm_split_k0, tp.sm_split_k1, gc, s0, s1);
                if (!streamsReady) {
                    fprintf(stderr, "SKIP %s path=%s: green context setup failed\n",
                            tp.test_point_id.c_str(), path.c_str());
                    freeBuffer(A0); freeBuffer(B0); freeBuffer(C0);
                    freeBuffer(A1); freeBuffer(B1); freeBuffer(C1);
                    continue;
                }
            } else {
                CUDA_CHECK(cudaStreamCreate(&s0));
                CUDA_CHECK(cudaStreamCreate(&s1));
                streamsReady = true;
            }

            for (int reuseN : reuseNs) {
                CellResult r = measureConcurrentCell(A0, B0, C0, n0, A1, B1, C1, n1, tp.blocks_k0,
                                                      tp.blocks_k1, tp.threads_per_block, reuseN, s0,
                                                      s1, trials);

                if (!didCorrectnessCheck) {
                    bool ok0 = checkCorrectness(C0, n0);
                    bool ok1 = checkCorrectness(C1, n1);
                    if (!ok0 || !ok1) {
                        fprintf(stderr, "CORRECTNESS FAILURE at %s path=%s (k0=%d k1=%d)\n",
                                tp.test_point_id.c_str(), path.c_str(), ok0, ok1);
                        anyCorrectnessFail = true;
                    }
                    didCorrectnessCheck = true;
                }

                if (r.wall_relstd > 0.05) {
                    fprintf(stderr,
                            "WARNING: high variance (stddev/median=%.3f) at %s path=%s reuse=%d\n",
                            r.wall_relstd, tp.test_point_id.c_str(), path.c_str(), reuseN);
                }

                bool haveDelta = true;
                double deltaPct = 0.0;
                if (path == "cached") {
                    cachedAggByReuse[reuseN] = r.agg_GBps_median;
                    deltaPct = 0.0;
                } else {
                    auto it = cachedAggByReuse.find(reuseN);
                    if (it != cachedAggByReuse.end() && it->second > 0) {
                        deltaPct = (r.agg_GBps_median - it->second) / it->second * 100.0;
                    } else {
                        haveDelta = false;  // cached baseline wasn't run (e.g. profiling mode)
                    }
                }
                char deltaStr[32];
                if (haveDelta) snprintf(deltaStr, sizeof(deltaStr), "%.3f", deltaPct);
                else snprintf(deltaStr, sizeof(deltaStr), "NA");

                char smSplit[32];
                snprintf(smSplit, sizeof(smSplit), "%d:%d", tp.sm_split_k0, tp.sm_split_k1);

                fprintf(csv,
                        "%s,%s,%s,%s,%zu,%zu,%d,%s,%d,%d,%d,%d,%d,%.6f,%.3f,%.3f,%.3f,%s,NA,NA,"
                        "%d,%s,%.1f,%s,%s\n",
                        tp.test_point_id.c_str(), tp.mode.c_str(), tp.config.c_str(), smSplit,
                        tp.k0_bytes, tp.k1_bytes, tp.large_kernel_id, path.c_str(), reuseN,
                        tp.blocks_k0, tp.blocks_k1, tp.threads_per_block, trials, r.wall_ms_median,
                        r.agg_GBps_median, r.k0_GBps_median, r.k1_GBps_median, deltaStr,
                        env.gpu_clock_mhz, env.power_mode.c_str(), env.soc_temp_c,
                        env.cuda_version.c_str(), env.driver_version.c_str());
            }

            if (tp.config == "green") {
                destroyGreenContext(gc, s0, s1);
            } else {
                CUDA_CHECK(cudaStreamDestroy(s0));
                CUDA_CHECK(cudaStreamDestroy(s1));
            }

            freeBuffer(A0); freeBuffer(B0); freeBuffer(C0);
            freeBuffer(A1); freeBuffer(B1); freeBuffer(C1);
        }

        fprintf(stderr, "done test_point=%s\n", tp.test_point_id.c_str());
    }

    fclose(csv);

    if (anyCorrectnessFail) {
        fprintf(stderr, "STOP: correctness check failed, see above.\n");
        return 1;
    }
    fprintf(stderr, "Wrote %s\n", outPath.c_str());
    return 0;
}
